from datetime import date, timedelta
def wd(d):
    return ['seg','ter','qua','qui','sex','sáb','dom'][d.weekday()]
def fmt(d): return f"{d:%d/%m/%Y} ({wd(d)})"
HOL={date(2026,11,20),date(2026,12,8),date(2026,12,24),date(2026,12,25),date(2026,12,31),date(2027,1,1)}
def util(d): return d.weekday()<5 and d not in HOL
def sus(d): return date(2026,12,20)<=d<=date(2027,1,20)
cnt=date(2026,11,23); hit=0   # dia do começo = publicação 23/11, excluido
while hit<30:
    cnt+=timedelta(days=1)
    if util(cnt) and not sus(cnt):
        hit+=1
        if hit>=16 or hit<=15: pass
        print(hit, fmt(cnt))
print("DOBRO HIPOTETICO (30 dias uteis):", fmt(cnt))
EOF
python3 /tmp/opencode/dobro_hipotetico.py"}
